#include <iostream>
#include <vector>
using namespace std;

void siftDown(vector<int>& arr, int i, int n) {
    int smallest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left < n && arr[left] < arr[smallest]) smallest = left;
    if (right < n && arr[right] < arr[smallest]) smallest = right;

    if (smallest != i) {
        swap(arr[i], arr[smallest]);
        siftDown(arr, smallest, n);
    }
}

void buildHeap(vector<int>& arr) {
    int n = arr.size();
    for (int i = n / 2 - 1; i >= 0; i--) {
        siftDown(arr, i, n);
    }
}

int main() {
    vector<int> arr = {9, 4, 7, 1, -2, 6, 5};
    buildHeap(arr);

    for (int x : arr) {
        cout << x << " ";
    }
    return 0;
}

