import java.util.PriorityQueue;

public class Main {
    public static void main(String[] args) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();

        minHeap.offer(8);     // insert
        minHeap.offer(3);
        minHeap.offer(5);

        System.out.println(minHeap.peek());       // get min -> 3  (no removal)
        System.out.println(minHeap.poll());       // extract min -> 3
        System.out.println(minHeap.size());       // 2
    }
}

