#include <iostream>
#include <queue>
#include <vector>
using namespace std;

int main() {
    priority_queue<int, vector<int>, greater<int>> minHeap;

    minHeap.push(8);     // insert
    minHeap.push(3);
    minHeap.push(5);

    cout << minHeap.top() << endl;   // get min -> 3  (no removal)
    int extracted = minHeap.top();
    minHeap.pop();
    cout << extracted << endl;       // extract min -> 3
    cout << minHeap.size() << endl;  // 2

    return 0;
}
